import type { ItrSalaryTds } from '../itr/itrCommon.js';
import { PAN_RE, TAN_RE, maskPanValue, normLabel, parseAmount, parseDate, round2, type StatementIssue } from './common.js';

/**
 * Form 16 (Form 130 under the Income-tax Act 2025) read from the text layer of the PDF that TRACES
 * produces, line by line (see textLines in ./common.ts for how pdf.js text items become lines).
 *
 * Part A is generated by TRACES for every employer, so its layout is fixed: the employer and
 * employee block (names, deductor PAN and TAN, employee PAN, assessment year, period with the
 * employer) and the quarter table Q1 to Q4 with the receipt number of the quarterly statement,
 * amount paid or credited, tax deducted and tax deposited, then a Total line. The labels matched
 * here are those printed on Form 16 Part A under rule 31 of the Income-tax Rules 1962.
 *
 * Part B (the annexure) is prepared by the employer, often in its own payroll software, so its
 * layout varies. Each figure is found by the wording of its label in the rule 31 Form 16 Part B
 * (for example "Salary as per provisions contained in section 17(1)", "Standard deduction under
 * section 16(ia)", "Tax on employment under section 16(iii)"), matched loosely, and the figure is
 * the last amount on that line (or on the next line when the label wraps). Whatever is not found
 * is listed in `missing`, so nothing is filled in silently.
 *
 * Unconfirmed: the Form 130 layout under the 2025 Act. Its first certificates will be for Tax Year
 * 2026-27 (issued after March 2027); the labels below follow the rule 31 Form 16 and will need
 * checking against Form 130 once TRACES issues it. Labels that name a section of the 1961 Act are
 * matched by their words as well, so a renumbered section alone should not stop a match.
 *
 * This reads certificates only. It never writes or fills a Form 16 or Form 130.
 */

export type Form16Field =
  | 'salary171' | 'perquisites172' | 'profits173' | 'grossSalary' | 'otherEmployerSalary'
  | 'exemptTravel' | 'exemptGratuity' | 'exemptPension' | 'exemptLeave' | 'exemptHra' | 'exemptOther' | 'exemptTotal'
  | 'salaryCurrentEmployer' | 'standardDeduction' | 'entertainmentAllowance' | 'professionalTax' | 'deductions16'
  | 'chargeableSalary' | 'houseProperty' | 'otherSources' | 'grossTotalIncome'
  | 'ded80C' | 'ded80CCC' | 'ded80CCD1' | 'ded80CCD1B' | 'ded80CCD2' | 'ded80D' | 'ded80E' | 'ded80G' | 'ded80TTA' | 'ded80TTB' | 'chapterVIATotal'
  | 'totalTaxableIncome' | 'taxOnTotalIncome' | 'rebate87A' | 'surcharge' | 'cess' | 'taxPayable' | 'relief89' | 'netTaxPayable';

interface FieldRule { key: Form16Field; label: string; re: RegExp; important?: boolean }

/** Checked in order, most specific first; matched against the line after normLabel. */
const PART_B_RULES: FieldRule[] = [
  { key: 'otherEmployerSalary', label: 'Salary from other employers', re: /salary received from other employer/ },
  { key: 'salaryCurrentEmployer', label: 'Salary from current employer (gross less section 10 exemptions)', re: /total amount of salary received from current employer/, important: true },
  { key: 'salary171', label: 'Salary under section 17(1)', re: /salary as per provisions contained in section 17 ?1\b|salary as per section 17 ?1\b/ },
  { key: 'perquisites172', label: 'Perquisites under section 17(2)', re: /value of perquisites|perquisites under section 17 ?2\b/ },
  { key: 'profits173', label: 'Profits in lieu of salary under section 17(3)', re: /profits? in lieu of salary/ },
  { key: 'exemptTotal', label: 'Total exemption under section 10', re: /total amount of exemptions? claimed under section 10|total exemptions? under section 10/ },
  { key: 'exemptTravel', label: 'Travel concession, section 10(5)', re: /travel concession|leave travel/ },
  { key: 'exemptGratuity', label: 'Gratuity, section 10(10)', re: /gratuity/ },
  { key: 'exemptPension', label: 'Commuted pension, section 10(10A)', re: /commuted value of pension|commuted pension/ },
  { key: 'exemptLeave', label: 'Leave encashment, section 10(10AA)', re: /leave salary encashment|leave encashment/ },
  { key: 'exemptHra', label: 'House rent allowance, section 10(13A)', re: /house rent allowance|\bhra\b/ },
  { key: 'exemptOther', label: 'Other exemptions under section 10', re: /amount of any other exemption under section 10|other exemptions? under section 10/ },
  { key: 'standardDeduction', label: 'Standard deduction, section 16(ia)', re: /standard deduction/, important: true },
  { key: 'entertainmentAllowance', label: 'Entertainment allowance, section 16(ii)', re: /entertainment allowance/ },
  { key: 'professionalTax', label: 'Professional tax, section 16(iii)', re: /tax on employment|professional tax/, important: true },
  { key: 'deductions16', label: 'Total deductions under section 16', re: /total amount of deductions under section 16|total deductions? under section 16/ },
  { key: 'chargeableSalary', label: 'Income chargeable under the head Salaries', re: /income chargeable under the head salar/, important: true },
  { key: 'houseProperty', label: 'House property income offered for TDS', re: /from house property/ },
  { key: 'otherSources', label: 'Other sources income offered for TDS', re: /head other sources|income from other sources/ },
  { key: 'grossTotalIncome', label: 'Gross total income', re: /gross total income/ },
  { key: 'chapterVIATotal', label: 'Total of Chapter VI-A deductions', re: /aggregate of deductible amount under chapter vi ?a|total deductions? under chapter vi ?a|total of chapter vi ?a/ },
  { key: 'ded80CCD1B', label: '80CCD(1B)', re: /80 ?ccd ?1 ?b\b/ },
  { key: 'ded80CCD2', label: '80CCD(2)', re: /80 ?ccd ?2\b/ },
  { key: 'ded80CCD1', label: '80CCD(1)', re: /80 ?ccd ?1\b/ },
  { key: 'ded80CCC', label: '80CCC', re: /80 ?ccc\b/ },
  { key: 'ded80C', label: '80C', re: /section 80 ?c\b|\b80 ?c\b(?! ?c)/ },
  { key: 'ded80D', label: '80D', re: /\b80 ?d\b|health insurance premia/ },
  { key: 'ded80E', label: '80E', re: /\b80 ?e\b|loan taken for higher education/ },
  { key: 'ded80G', label: '80G', re: /\b80 ?g\b|donations to certain funds/ },
  { key: 'ded80TTA', label: '80TTA', re: /80 ?tta\b/ },
  { key: 'ded80TTB', label: '80TTB', re: /80 ?ttb\b/ },
  { key: 'totalTaxableIncome', label: 'Total taxable income', re: /total taxable income|^(\d+ )?total income\b/, important: true },
  { key: 'rebate87A', label: 'Rebate under section 87A', re: /rebate under section 87 ?a|\brebate\b/ },
  { key: 'relief89', label: 'Relief under section 89', re: /relief under section 89|\brelief\b/ },
  { key: 'netTaxPayable', label: 'Net tax payable', re: /net tax payable/, important: true },
  { key: 'taxOnTotalIncome', label: 'Tax on total income', re: /tax on total income/ },
  { key: 'cess', label: 'Health and education cess', re: /education cess|\bcess\b/ },
  { key: 'surcharge', label: 'Surcharge', re: /surcharge/ },
  { key: 'taxPayable', label: 'Tax payable', re: /(^|\s)tax payable/ },
];

export const FORM16_FIELD_LABELS: Record<Form16Field, string> = Object.fromEntries([
  ...PART_B_RULES.map((r) => [r.key, r.label]),
  ['grossSalary', 'Gross salary (total of 17(1), 17(2) and 17(3))'],
]) as Record<Form16Field, string>;

export interface Form16Quarter { quarter: 'Q1' | 'Q2' | 'Q3' | 'Q4'; receipt: string | null; paid: number; deducted: number; deposited: number }

export interface Form16Result {
  isForm16: boolean;
  /** Form 130 when the text names it, otherwise Form 16. */
  form: 'FORM16' | 'FORM130' | null;
  partA: {
    found: boolean;
    certificateNo: string | null;
    employerName: string | null;
    employerTan: string | null;
    /** Masked: XXXXX and the last five characters. */
    employerPan: string | null;
    employeePan: string | null;
    assessmentYear: string | null;
    periodFrom: string | null;
    periodTo: string | null;
    quarters: Form16Quarter[];
    totalPaid: number | null;
    totalDeducted: number | null;
    totalDeposited: number | null;
  };
  partB: {
    found: boolean;
    figures: Partial<Record<Form16Field, number>>;
    /** Lines the figure came from, for showing next to it. */
    sources: Partial<Record<Form16Field, string>>;
    /** NEW when the employee did not opt out of section 115BAC (new regime), OLD when they did; null when not stated. */
    regime: 'NEW' | 'OLD' | null;
  };
  /** Figures the reader looked for and did not find. */
  missing: Array<{ field: Form16Field | string; label: string }>;
  issues: StatementIssue[];
  /** Shaped for the ITR salary inputs (ItrSalaryTds and the employer row of ITR-2 and ITR-3). */
  itr: {
    salaryTds: ItrSalaryTds | null;
    /** Salary from this employer after section 10 exemptions: the gross the ITR writers take. */
    gross: number | null;
    professionalTax: number | null;
    deductions: { section80C: number | null; section80CCD1B: number | null; section80D: number | null };
  };
}

/** Leading item numbers like "1.", "(a)", "2(h)", "iv." taken off a line before reading its label. */
const stripEnumerator = (s: string) => s.replace(/^\s*(\(?\d{1,2}\)?\s*\(?[a-z]{0,4}\)|\d{1,2}[.)]|\(?[a-z]{1,4}\)|[ivx]{1,4}\.)\s*/i, '');

/**
 * Amounts on a line, left to right. Section numbers ("17(1)", "80C", "16(ia)") are not amounts
 * because they carry letters or brackets; bare small integers are taken only at the end of a line
 * and only when the line has no amount with paise.
 */
export function amountsOnLine(line: string): number[] {
  const body = stripEnumerator(line);
  const tokens = body.split(/\s+/).filter(Boolean);
  const withPaise: number[] = [];
  const plain: number[] = [];
  tokens.forEach((t, i) => {
    const prev = (tokens[i - 1] ?? '').toLowerCase();
    if (/^(section|sec|u\/s|under|rule)$/.test(prev)) return;
    const v = parseAmount(t);
    if (v === null) return;
    if (/\.\d{1,2}\)?$/.test(t)) withPaise.push(v);
    else plain.push(v);
  });
  if (withPaise.length) return withPaise;
  const last = tokens[tokens.length - 1];
  return last && parseAmount(last) !== null && !/\.\d{3,}/.test(last) ? plain : [];
}

const onlyAmounts = (line: string | undefined) => !!line && !/[a-z]/i.test(line.replace(/\bRs\.?|\bINR\b/gi, '')) && amountsOnLine(line).length > 0;

function findAfter(lines: string[], re: RegExp, within = 6): string | null {
  const i = lines.findIndex((l) => re.test(l));
  if (i < 0) return null;
  return lines.slice(i, i + within).join('  ');
}

export function parseForm16(lines: string[]): Form16Result {
  const issues: StatementIssue[] = [];
  const missing: Form16Result['missing'] = [];
  const clean = lines.map((l) => l.replace(/\s+$/, '')).filter((l) => l.trim());
  const all = clean.join('\n');
  const form: Form16Result['form'] = /form\s*(no\.?)?\s*130\b/i.test(all) ? 'FORM130' : /form\s*(no\.?)?\s*16\b/i.test(all) ? 'FORM16' : null;

  // Part A runs up to the "Part B" heading (TRACES prints "PART B (Annexure)").
  let bStart = clean.findIndex((l) => /^\s*part\s*[-\s]?b\b|\bpart\s*b\s*\(?annexure/i.test(l));
  const aStart = clean.findIndex((l) => /^\s*part\s*[-\s]?a\b/i.test(l));
  if (bStart < 0) bStart = clean.findIndex((l) => /details of salary paid and any other income and tax deducted/i.test(l));
  const aLines = bStart > 0 ? clean.slice(0, bStart) : clean;
  const bLines = bStart >= 0 ? clean.slice(bStart) : clean;
  const aText = aLines.join('\n');

  // Part A
  const certificateNo = /certificate\s*no\.?\s*:?\s*([A-Z0-9]{5,12})\b/i.exec(aText)?.[1] ?? null;
  const tan = TAN_RE.exec(aText)?.[1] ?? null;
  const pans = [...new Set([...aText.matchAll(new RegExp(PAN_RE.source, 'g'))].map((m) => m[1]))];
  let employerPan: string | null = null;
  let employeePan: string | null = null;
  if (pans.length >= 2) [employerPan, employeePan] = pans;
  else if (pans.length === 1) {
    if (pans[0][3] === 'P') employeePan = pans[0];
    else employerPan = pans[0];
  }

  const ayBlock = findAfter(aLines, /assessment\s*year|tax\s*year/i, 4) ?? '';
  const assessmentYear = /\b(20\d{2})\s*-\s*(\d{2})\b/.exec(ayBlock.replace(/.*?(assessment|tax)\s*year/is, ''))?.slice(1, 3).join('-') ?? null;

  const periodBlock = findAfter(aLines, /period\s*with\s*the\s*employer/i, 4) ?? '';
  const dates = [...periodBlock.matchAll(/\b(\d{1,2}[-/.](?:[A-Za-z]{3}|\d{1,2})[-/.]\d{4})\b/g)].map((m) => parseDate(m[1])).filter((d): d is string => !!d);

  let employerName: string | null = null;
  const nameIdx = aLines.findIndex((l) => /name\s*and\s*address\s*of\s*the\s*employer/i.test(l));
  if (nameIdx >= 0) {
    const next = aLines[nameIdx + 1] ?? '';
    const first = next.split(/\s{2,}/)[0]?.trim();
    if (first && !/name\s*and\s*address/i.test(first) && !PAN_RE.test(first) && !TAN_RE.test(first)) employerName = first.slice(0, 125);
  }

  const quarters: Form16Quarter[] = [];
  let totals: number[] | null = null;
  for (const l of aLines) {
    const q = /^\s*(Q[1-4])\b\s*(.*)$/.exec(l);
    if (q) {
      const receipt = /\b([A-Z]{8})\b/.exec(q[2])?.[1] ?? null;
      const nums = amountsOnLine(q[2].replace(/\b[A-Z]{8}\b/, ' '));
      if (nums.length >= 3) quarters.push({ quarter: q[1] as Form16Quarter['quarter'], receipt, paid: nums[nums.length - 3], deducted: nums[nums.length - 2], deposited: nums[nums.length - 1] });
      else issues.push({ field: q[1], message: `The ${q[1]} line in Part A did not have the three amounts (paid, deducted, deposited).` });
      continue;
    }
    if (quarters.length && !totals && /^\s*total\b/i.test(l)) {
      const nums = amountsOnLine(l);
      if (nums.length >= 3) totals = nums.slice(-3);
    }
  }
  const sumQ = (k: 'paid' | 'deducted' | 'deposited') => round2(quarters.reduce((s, q) => s + q[k], 0));
  const totalPaid = totals ? totals[0] : quarters.length ? sumQ('paid') : null;
  const totalDeducted = totals ? totals[1] : quarters.length ? sumQ('deducted') : null;
  const totalDeposited = totals ? totals[2] : quarters.length ? sumQ('deposited') : null;
  if (totals && quarters.length && Math.abs(totals[1] - sumQ('deducted')) > 1) issues.push({ field: 'partA', message: 'The Part A total of tax deducted does not equal the sum of the quarters read; check the quarter lines.' });
  const partAFound = !!(tan || quarters.length);

  if (!tan) missing.push({ field: 'employerTan', label: 'Employer TAN' });
  if (!employeePan) missing.push({ field: 'employeePan', label: 'Employee PAN' });
  if (!quarters.length) missing.push({ field: 'quarters', label: 'Part A quarter table (Q1 to Q4)' });
  if (!employerName) missing.push({ field: 'employerName', label: 'Employer name' });
  if (!assessmentYear) missing.push({ field: 'assessmentYear', label: 'Assessment year' });

  // Part B
  const figures: Partial<Record<Form16Field, number>> = {};
  const sources: Partial<Record<Form16Field, string>> = {};
  const used = new Set<number>();
  let afterProfits = false;
  let gross1d: number | null = null;
  bLines.forEach((line, i) => {
    const n = normLabel(stripEnumerator(line));
    if (!n) return;
    // 1(d): the "Total" right after the 17(1), 17(2), 17(3) block.
    if (afterProfits && gross1d === null && /^(\(?d\)?\s*)?total\b/.test(n) && !/total (amount|taxable|income|deduction|of)/.test(n)) {
      const a = amountsOnLine(line);
      if (a.length) {
        gross1d = a[a.length - 1];
        sources.grossSalary = line.trim();
      }
      afterProfits = false;
      return;
    }
    if (/^gross salary\b/.test(n) && figures.grossSalary === undefined) {
      const a = amountsOnLine(line);
      if (a.length) {
        figures.grossSalary = a[a.length - 1];
        sources.grossSalary = line.trim();
      }
    }
    // "Total deduction under sections 80C, 80CCC and 80CCD(1)" is a subtotal, not one section.
    if (/total deductions? under sections? 80 ?c.*80 ?ccc/.test(n)) return;
    const rule = PART_B_RULES.find((r) => r.re.test(n));
    if (!rule || figures[rule.key] !== undefined) return;
    if (rule.key === 'profits173') afterProfits = true;
    let amounts = amountsOnLine(line);
    let from = line;
    if (!amounts.length) {
      for (const j of [i + 1, i + 2, i - 1]) {
        if (j >= 0 && j < bLines.length && !used.has(j) && onlyAmounts(bLines[j])) {
          amounts = amountsOnLine(bLines[j]);
          from = `${line.trim()}  ${bLines[j].trim()}`;
          used.add(j);
          break;
        }
      }
    }
    if (!amounts.length) return;
    figures[rule.key] = amounts[amounts.length - 1];
    sources[rule.key] = from.trim();
    used.add(i);
  });
  if (gross1d !== null) figures.grossSalary = gross1d;
  if (figures.grossSalary === undefined && (figures.salary171 !== undefined || figures.perquisites172 !== undefined || figures.profits173 !== undefined)) {
    figures.grossSalary = round2((figures.salary171 ?? 0) + (figures.perquisites172 ?? 0) + (figures.profits173 ?? 0));
    sources.grossSalary = 'Added from 17(1), 17(2) and 17(3)';
  }

  let regime: 'NEW' | 'OLD' | null = null;
  const regimeLine = bLines.findIndex((l) => /115\s*BAC/i.test(l) && /opt/i.test(l));
  if (regimeLine >= 0) {
    const txt = `${bLines[regimeLine]} ${bLines[regimeLine + 1] ?? ''}`;
    const ans = /\b(yes|no)\b/i.exec(txt.replace(/.*115\s*BAC[^A-Za-z]*(\(1A\))?/i, ''));
    const optingOut = /opting\s*out|opted\s*out/i.test(txt);
    if (ans) regime = (ans[1].toLowerCase() === 'yes') === optingOut ? 'OLD' : 'NEW';
  }

  const partBFound = Object.keys(figures).length >= 3;
  if (partBFound) {
    for (const r of PART_B_RULES) if (r.important && figures[r.key] === undefined) missing.push({ field: r.key, label: r.label });
    if (figures.grossSalary === undefined) missing.push({ field: 'grossSalary', label: FORM16_FIELD_LABELS.grossSalary });
    if (regime === null) missing.push({ field: 'regime', label: 'Whether the employee opted out of the new regime (section 115BAC)' });
  } else missing.push({ field: 'partB', label: 'Part B (salary break-up). Upload the Part B file as well if the employer issued it separately.' });

  // Form 16 arithmetic: item 3 = 1(d) less 2(h); salary chargeable = item 3 (+ other employers) less item 5.
  let gross = figures.salaryCurrentEmployer ?? null;
  if (gross === null && figures.grossSalary !== undefined) gross = round2(figures.grossSalary - (figures.exemptTotal ?? 0));
  if (figures.salaryCurrentEmployer !== undefined && figures.grossSalary !== undefined && figures.exemptTotal !== undefined
    && Math.abs(figures.grossSalary - figures.exemptTotal - figures.salaryCurrentEmployer) > 1) {
    issues.push({ field: 'salaryCurrentEmployer', message: 'Gross salary less section 10 exemptions does not equal the salary from current employer in Part B; check which figures were read.' });
  }
  if (totalDeducted !== null && figures.netTaxPayable !== undefined && Math.abs(totalDeducted - figures.netTaxPayable) > 1) {
    issues.push({ field: 'tds', message: 'Tax deducted in Part A differs from net tax payable in Part B. This is common when there was another employer or a refund; check before filing.' });
  }
  const isForm16 = !!form || partAFound || partBFound;
  if (!isForm16) issues.push({ field: 'file', message: 'This does not look like a Form 16 or Form 130: no TAN, quarter table or salary labels were found.' });
  if (!form && isForm16) issues.push({ field: 'file', message: 'The form number was not found in the text; the figures were read by their labels.' });

  const chargeable = figures.chargeableSalary ?? null;
  return {
    isForm16,
    form,
    partA: {
      found: partAFound, certificateNo, employerName, employerTan: tan,
      employerPan: employerPan ? maskPanValue(employerPan) : null, employeePan: employeePan ? maskPanValue(employeePan) : null,
      assessmentYear, periodFrom: dates[0] ?? null, periodTo: dates[1] ?? null,
      quarters, totalPaid, totalDeducted, totalDeposited,
    },
    partB: { found: partBFound, figures, sources, regime },
    missing,
    issues,
    itr: {
      salaryTds: tan || totalDeducted !== null ? { tan: tan ?? '', name: employerName ?? '', incomeChargeable: Math.round(chargeable ?? gross ?? totalPaid ?? 0), tds: Math.round(totalDeducted ?? 0) } : null,
      gross: gross === null ? null : Math.round(gross),
      professionalTax: figures.professionalTax === undefined ? null : Math.round(figures.professionalTax),
      deductions: { section80C: figures.ded80C ?? null, section80CCD1B: figures.ded80CCD1B ?? null, section80D: figures.ded80D ?? null },
    },
  };
}
